<?php require __DIR__.'/../includes/bootstrap.php';if(!collector_marketplace_ready())redirect('collectors/index.php');$i=collector_item_by_slug($_GET['slug']??'');if(!$i||(!in_array($i['status'],['active','sold','traded'],true)&&(!user()||(int)user()['id']!==(int)$i['seller_user_id']&&(user()['role']??'')!=='admin'))){http_response_code(404);exit('Item not found.');}if($_SERVER['REQUEST_METHOD']==='POST'){require_auth();verify_csrf();$action=$_POST['action']??'';if($action==='favorite'){db()->prepare('INSERT IGNORE INTO collector_favorites(user_id,item_id) VALUES(?,?)')->execute([(int)user()['id'],$i['id']]);flash('success','Added to favorites.');}elseif($action==='offer'){if((int)user()['id']===(int)$i['seller_user_id'])flash('error','You cannot make an offer on your own item.');else{db()->prepare('INSERT INTO collector_offers(item_id,buyer_user_id,offer_type,amount,trade_details,message) VALUES(?,?,?,?,?,?)')->execute([$i['id'],(int)user()['id'],$_POST['offer_type']??'cash',($_POST['amount']??'')!==''?(float)$_POST['amount']:null,trim($_POST['trade_details']??''),trim($_POST['message']??'')]);flash('success','Offer sent.');}}redirect_route('collectors/item.php',['slug'=>$i['slug']]);}app_header($i['title']);?><section class="product-layout"><div><?php if($i['image_path']):?><img class="product-main-image" src="<?=e(base_url($i['image_path']))?>" alt=""><?php endif?></div><article class="form-card"><p class="eyebrow"><?=e(strtoupper(collector_listing_types()[$i['listing_type']]??''))?></p><h1><?=e($i['title'])?></h1><p><a href="view.php?slug=<?=urlencode($i['collector_slug'])?>"><?=e($i['shop_name'])?></a></p><div class="pill-row"><span class="pill"><?=e(collector_categories()[$i['category']]??$i['category'])?></span><?php if($i['condition_grade']):?><span class="pill"><?=e($i['condition_grade'])?></span><?php endif?><span class="pill"><?=e(ucfirst($i['status']))?></span></div><p><?=nl2br(e($i['description']))?></p><h2><?=$i['price']!==null?'$'.number_format((float)$i['price'],2):'Open to offers'?></h2><?php if(user()&&(int)user()['id']!==(int)$i['seller_user_id']):?><form method="post" class="stack"><?=csrf_field()?><input type="hidden" name="action" value="favorite"><button class="button ghost">Add to Favorites</button></form><form method="post" class="stack"><?=csrf_field()?><input type="hidden" name="action" value="offer"><label>Offer type<select name="offer_type"><option value="cash">Cash offer</option><option value="trade">Trade offer</option><option value="message">Question / message</option></select></label><label>Amount<input type="number" step="0.01" min="0" name="amount"></label><label>Trade details<textarea name="trade_details"></textarea></label><label>Message<textarea name="message"></textarea></label><button class="button primary">Send Offer</button></form><?php elseif(!user()):?><p><a class="button primary" href="../login.php">Log in to make an offer</a></p><?php endif?></article></section><?php
$relatedItems=[];
foreach(gnm_safe_rows("SELECT ci.title,ci.slug,ci.description,ci.image_path,ci.price,ci.listing_type FROM collector_items ci WHERE ci.collector_id=? AND ci.id<>? AND ci.status='active' ORDER BY ci.is_featured DESC,ci.updated_at DESC LIMIT 4",[(int)$i['collector_id'],(int)$i['id']]) as $row){$relatedItems[]=['title'=>$row['title'],'description'=>$row['price']!==null?'$'.number_format((float)$row['price'],2):($row['description']?:'Open to offers'),'href'=>base_url('collectors/item.php?slug='.urlencode($row['slug'])),'image'=>$row['image_path']?base_url($row['image_path']):'','icon'=>'star','eyebrow'=>'MORE FROM THIS COLLECTOR'];}
foreach(gnm_safe_rows("SELECT ci.title,ci.slug,ci.description,ci.image_path,ci.price,ci.listing_type FROM collector_items ci WHERE ci.id<>? AND ci.status='active' AND ((?<>'' AND ci.franchise=?) OR ci.category=?) ORDER BY ci.is_featured DESC,ci.updated_at DESC LIMIT 4",[(int)$i['id'],(string)($i['franchise']??''),(string)($i['franchise']??''),(string)$i['category']]) as $row){$relatedItems[]=['title'=>$row['title'],'description'=>$row['price']!==null?'$'.number_format((float)$row['price'],2):($row['description']?:'Open to offers'),'href'=>base_url('collectors/item.php?slug='.urlencode($row['slug'])),'image'=>$row['image_path']?base_url($row['image_path']):'','icon'=>'star','eyebrow'=>'RELATED COLLECTIBLE'];}
gnm_related_section('More Collectibles','Explore Collectors Marketplace',base_url('collectors/index.php'),array_slice($relatedItems,0,8),'More items from this collector and related listings will appear here.');
?>
<?php app_footer();
